fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box), select the Lists application, and stay on the default 'Lists' (Browse) section. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) list-share-dialog — on any list you own, click its '...' (ellipsis) more-options button to open the context menu, then click 'Share' and confirm the share dialog opens showing sharing controls (permission levels and a way to add a user or role); do NOT actually share — Cancel/close the dialog; (2) list-delete-guard — on any list you own, click its '...' more-options button and choose 'Delete', then confirm a 'Delete List' confirmation dialog appears warning it will also remove all items in the list; click 'Cancel' and confirm the list is NOT deleted (it still appears). Do NOT click the red Delete button. If you own no lists at all, confirming the Browse section renders cleanly with a valid empty-state is acceptable for that checkpoint. Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "list-share-dialog",
      "instruction": "open a list's context menu and the Share dialog",
      "visualCriteria": [
        "A list's '...' context menu opens and offers a 'Share' item, and choosing it opens a share dialog exposing sharing controls (permission level selection and/or an add-user/role input); cancelling returns to the lists view without sharing"
      ]
    },
    {
      "name": "list-delete-guard",
      "instruction": "open the Delete confirmation guard and cancel without deleting",
      "visualCriteria": [
        "Choosing 'Delete' from a list's context menu opens a 'Delete List' confirmation dialog warning it will also remove all items in the list, and clicking 'Cancel' dismisses the dialog with the list still present (nothing deleted) — OR no owned lists exist and a valid empty-state renders"
      ]
    }
  ]
}
